import{_ as E}from"./chunks/image-002.Dp2-bnLm.js";import{_ as Q,o as g,c as B,a3 as o}from"./chunks/framework.DdpBa4_E.js";const A="data:image/gif;base64,",D=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/20-园池第十三.md","filePath":"books/yan-tie-lun/20-园池第十三.md","lastUpdated":1794316978000}'),C={name:"books/yan-tie-lun/20-园池第十三.md"};function a(I,p,i,t,c,s){return g(),B("div",null,[...p[0]||(p[0]=[o('<p>园池第十三 【题解】</p><p>本篇记载大夫与文学在天子诸侯园池存废问题上展开的论争。从司马相如《子虚》、《上林》中，我们看到汉代天子诸侯的山林苑囿是何等富丽壮观。这些园林池苑既满足天子诸侯的游乐田猎需求，同时园池的经营收入又作为天子诸侯的“小金库”，用来弥补国家财政的不足。文中大夫陈述朝廷经营园池山海的经济意义，认为罢园池会导致国家财政困乏。文学则主张制民之产，维护中国传统的男耕女织方式，要求朝廷将园池还归于民，朝廷所做的仅限于征收赋税，认为这样做会使上下丰饶，避免出现国富民穷的现象。</p><p>大夫曰：“诸侯以国为家[(1)]，其忧在内。天子以八极为境[(2)]，其虑在外。故宇小者用菲[(3)]，功巨者用大[(4)]。是以县官开园池[(5)]，总山海[(6)]，致利以助贡赋[(7)]，修沟渠，立诸农[(8)]，广田牧[(9)]，盛苑囿[(10)]。太仆、水衡、少府、大农[(11)]，岁课诸入田牧之利[(12)]，池籞之假[(13)]，及北边置任田官[(14)]，以赡诸用[(15)]，而犹未足。今欲罢之，绝其源，杜其流，上下俱殚[(16)]，困乏之应也[(17)]，虽好省事节用，如之何其可也[(18)]？”</p><p>【注释】</p><p>[(1)]国：封国。家：统治区域。</p><p>[(2)]八极：八方。境：边境。</p><p>[(3)]宇：疆土，一说为器宇。菲：少，薄。</p><p>[(4)]功：功用。巨：大。</p><p>[(5)]县官：朝廷，官府。园池：园林池苑。</p><p>[(6)]总：统一管理。山海：山林河海。</p><p>[(7)]致利：获取财利。助：补助。贡赋：赋税。</p><p>[(8)]诸农：诸位农官，指大司农属官，如太仓、均输、平准、都内、籍田五令丞等。</p><p>[(9)]广：拓展。田：田园。牧：牧场。原作“收”，据王先谦说校改。</p><p>[(10)]盛：增设。苑囿：古代畜养禽兽的地方，大的叫苑，小的叫囿。一说，养鸟兽曰苑，苑有垣墙叫囿。</p><p>[(11)]太仆：掌管牧场的官员。水衡：水衡都尉，掌管水泽的官员。少府：掌管山林池海税收的官员。大农：大司农。</p><p>[(12)]岁课：按年交纳的赋税。诸入：各项赋税收入。田牧之利：田园牧场的财利。牧，原作“收”，据王先谦说校改。</p><p>[(13)]籞（yù）：帝王的禁苑。假：出租。</p><p>[(14)]及北边置任田官：本句多一“任”字，据卢文弨说校删。田官，屯田官员。</p><p>[(15)]赡：供给。诸用：国家各项开支。</p><p>[(16)]殚：竭尽。</p><p>[(17)]困乏：贫困。应：效应。</p><p>[(18)]如之何其可：怎么可以。</p><p><img src="'+E+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“诸侯以封国为家，他们所忧在封国之内。天子以八方之极为边境，他的忧虑在国都之外。因此国土面积小的诸侯费用少，功用巨大的天子费用多。所以朝廷广开园林池苑，委派官员统一管理山林河海，获取财利来弥补赋税的不足，朝廷组织民众修筑沟渠，设立太仓、均输、平准、都内等各种农官，拓展田园牧场，增设畜养禽兽的苑囿。太仆、水衡、少府、大农各位农官，他们每年征收的各种赋税收入，加上田园牧场的财利，陂池禁苑出租的租金，以及北边设置屯田官的收入，全都用来供给国家各项开支，如此尚且不够。如今文学想取消园池，这将会断了国家的财源，杜绝了财富流通，上下财路一起枯竭，国家贫困效应随之而来，即使努力减省事务，节省费用，又怎么可以呢？”</p><p>文学曰：“古者，制地足以养民[(1)]，民足以承其上[(2)]。千乘之国[(3)]，百里之地[(4)]，公侯伯子男[(5)]，各充其求赡其欲[(6)]。秦兼万国之地[(7)]，有四海之富，而意不赡[(8)]，非宇小而用菲，嗜欲多而下不堪其求也[(9)]。语曰：‘厨有腐肉，国有饥民；厩有肥马，路有</p><p><img src="'+A+'" alt="" loading="lazy"></p><p>人。’[(10)]今狗马之养，虫兽之食，岂特腐肉肥马之费哉[(11)]！无用之官，不急之作[(12)]，服淫侈之变[(13)]，无功而衣食县官者众，是以上不足而下困乏也。今不减除其本而欲赡其末[(14)]，设机利[(15)]，造田畜[(16)]，与百姓争荐草[(17)]，与商贾争市利，非所以明主德而相国家也[(18)]。夫男耕女绩[(19)]，天下之大业也。故古者分地而处之[(20)]，制田亩而事之[(21)]。是以业无不食之地[(22)]，国无乏作之民[(23)]。今县官之多张苑囿、公田、池泽，公家有鄣假之名[(24)]，而利归权家[(25)]。三辅迫近于山、河[(26)]，地狭人众，四方并凑[(27)]，粟米薪采[(28)]，不能相赡[(29)]。公田转假[(30)]，桑榆菜果不殖[(31)]，地力不尽[(32)]。愚以为非。先帝之开苑囿、池籞，可赋归之于民[(33)]，县官租税而已[(34)]。假税殊名，其实一也。夫如是，匹夫之力，尽于南亩[(35)]，匹妇之力，尽于麻枲[(36)]。田野辟，麻枲治，则上下俱衍[(37)]，何困乏之有矣？”</p><p>大夫默然，视其丞相、御史。</p><p>【注释】</p><p>[(1)]制地：制定田地制度，如周代有井田制，《孟子·滕文公上》载：“方里而井，井九百亩。其中为公田，八家皆私百亩，同养公田。公事毕，然后敢治私事。”</p><p>[(2)]承：供养。</p><p>[(3)]千乘之国：拥有一千辆兵车的诸侯国。先秦时期，人们按照拥有兵车数量来衡量诸侯国的大小。</p><p>[(4)]百里之地：为公、侯级别的诸侯国。</p><p>[(5)]公侯伯子男：五个级别的诸侯。《礼记·王制》载：“王者之制禄爵：公、侯、伯、子、男，凡五等……公、侯田方百里，伯七十里，子、男五十里。”</p><p>[(6)]充：满足。赡：赡养。</p><p>[(7)]兼：兼并。万国：实指山东六国，万国是夸张的说法。</p><p>[(8)]赡：满足。</p><p>[(9)]嗜：原作“者”，据王利器说校改。堪：胜任。</p><p>[(10)]厨有腐肉，国有饥民；厩（jiù）有肥马，路有</p><p><img src="'+A+'" alt="" loading="lazy"></p><p>（něi）人：见于《孟子·梁惠王上》：“庖有肥肉，厩有肥马，民有饥色，野有饿莩，此率兽而食人也。”厩，马棚。</p><p><img src="'+A+'" alt="" loading="lazy"></p><p>，通“馁”，饥饿。</p><p>[(11)]特：单独。肥马：原作“秣马”，据王利器说校改。</p><p>[(12)]作：兴作，工程。</p><p>[(13)]服淫侈之变：姚范说，“服”字之上可能脱三字。</p><p>[(14)]本：指造成国家财用不足的根源。末：末节，指通过园池兴利。</p><p>[(15)]设：设置。机：机构，指上文盐铁、酒榷、均输、平准各种兴利机构。利：财利。</p><p>[(16)]造：兴造，开辟。田：牧场。畜：饲养牲畜。</p><p>[(17)]荐草：茂盛的牧草。</p><p>[(18)]明主德：宣传君主恩德。相：辅助。</p><p>[(19)]绩：纺织。</p><p>[(20)]处：居住。</p><p>[(21)]制：原作“利”，据郭沫若说校改。事：耕种。</p><p>[(22)]业：产业。不食之地：指未曾耕种的土地。</p><p>[(23)]乏作之民：不务正业的民众。</p><p>[(24)]鄣：同“障”，阻塞，指筑堤蓄水。假：出租。</p><p>[(25)]权家：权贵家族。</p><p>[(26)]三辅：右扶风、左冯翊、京兆尹。山：华山。河：黄河。</p><p>[(27)]并凑：辐凑，聚会。</p><p>[(28)]粟米：粮食。薪采：柴火。采，原作“菜”，据张敦仁说校改。</p><p>[(29)]赡：充足。</p><p>[(30)]转假：转租。</p><p>[(31)]殖：种植。</p><p>[(32)]地力不尽：不能充分使用地力。</p><p>[(33)]赋归：归还。</p><p>[(34)]租税：用作动词，征收租税。</p><p>[(35)]南亩：泛指田地。</p><p>[(36)]麻枲（xǐ）：麻的总称。</p><p>[(37)]衍：丰饶。</p><p><img src="'+E+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“古时候，朝廷制定田地制度，足以养活民众，民众足以供奉上司。拥有千乘兵车的诸侯国，方圆百里的土地，公、侯、伯、子、男五等诸侯，各自都能满足生活欲求。秦王朝吞并山东六国土地，拥有四海财富，可是秦始皇之意并不满足，这并不是因为国土狭小，费用不足，而是由于秦始皇嗜欲太多，民众不能承受他的欲求。谚语说：‘宫廷厨中有腐肉，国内路边有饥民，宫廷马厩有肥马，道旁却有饥饿人。’如今朝廷狗马的饲养，鸟兽的喂食，岂止是腐肉肥马的费用呢！无用的官吏，不急需的工程，荒淫奢侈之风变化多端，没有功劳却从朝廷领取俸禄的人太多，因此朝廷财用不足，底层民众生活困乏。现在朝廷不减除造成财政不足的本源，却想从园池末节上求得富足，设置机构兴利，开辟牧场养畜，与百姓争夺饲养草料，与商人争夺利润，这不是用来宣传君主恩德、辅助国家的正确之道啊！男耕女织，自古是天下的大业。因此古代划定区域让民众居住，制定田亩制度让民众耕种。所以产业上没有不曾耕种的土地，国家没有不务正业的民众。现在朝廷广泛开辟苑囿、公田、池泽，公家有鄣塞、出租的名义，而利益却归于权贵私人家族。右扶风、左冯翊、京兆尹三辅靠近华山、黄河，土地狭小，人口众多，四方人众集中到京师，粮食柴火，不能满足。朝廷将公田转租，桑树、榆树、蔬菜、水果不能得到充分种植，地力没有得到充分使用。我认为朝廷这些政策错了。先朝皇帝所开辟的苑囿、池陂，可以将它们归还给民众，朝廷只需征收租税而已。转租公田，与征收赋税，虽然名称不同，其实是一样的。如果这样做，那么匹夫的气力，都会全部用在田地之上，匹妇的气力，就会全部用在纺织之上。田野得到开辟，丝麻得到纺织，那么国家和民众都会丰饶，哪里会有财用困乏的现象呢？”</p><p>大夫默不出声，看着丞相、御史。</p>',75)])])}const w=Q(C,[["render",a]]);export{D as __pageData,w as default};
